FEET[p.feet].st + (p.clinch ? 1 : 0);
/* RULES569 R5: the exchange that gets dearer. m.ex = the beats in a row this man has punched; a punching beat costs +1 stamina for each (at most N.dearMax). A beat with no punch or with a back off ends the exchange. */
const punches = (p) => !p.clinch && !!((p.lead && ACT[p.lead].d) || p.rear), dear = (m, p) => (N.dear && punches(p) ? N.dear * Math.min(m.ex || 0, N.dearMax) : 0); cost.dear = dear;
